def calculate_k(A, B):
    K = 0
    for m in A:
        count = 0
        for n in B:
            if abs(m - n) <= 1000:
                count += 1
        K += count
    return K

A = list(range(2000))
B = list(range(2016))
K = calculate_k(A, B)
print(f"K for A={A} and B={B}: {K}")

A = list(range(2000))  # {0, ..., 1999}
B = list(range(2016))  # {0, ..., 2015}
K = 0
for m in A:
    count = 0
    # n must satisfy |m-n| <= 1000, i.e., m - 1000 <= n <= m + 1000
    lower_bound_n = m - 1000
    upper_bound_n = m + 1000

    # We only need to count how many elements of B fall into [lower_bound_n, upper_bound_n]
    # B = {0, 1, ..., 2015}

    # The intersection of [lower_bound_n, upper_bound_n] and B (which is [0, 2015])
    # Start of overlap: max(0, lower_bound_n)
    # End of overlap: min(2015, upper_bound_n)

    start = max(0, lower_bound_n)
    end = min(2015, upper_bound_n)

    # The number of integers in [start, end] is end - start + 1, provided start <= end
    if start <= end:
        count = end - start + 1

    K += count

print(f"Calculated K: {K}")

